from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.models import Payment
from ledgerly.support import process_refund_request
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def p(status="captured", amt="100.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# rounding >2 decimals
x=p(); process_refund_request(x,"10.005","u",T0); print("round", x.refunded_amount)
# full refund status
x=p(); process_refund_request(x,"100.00","u",T0); print("full", x.refunded_amount, x.status)
# non-captured
try: process_refund_request(p("authorized"),"1.00","u",T0)
except BillingError as e: print("state", e.code)
# non-positive
try: process_refund_request(p(),"0","u",T0)
except BillingError as e: print("nonpos", e.code)
# over refund cumulative
x=p(); process_refund_request(x,"60.00","u",T0)
try: process_refund_request(x,"50.00","u",T0)
except BillingError as e: print("over", e.code, x.refunded_amount)
# approval threshold
try: process_refund_request(p("captured","1000.00"),"500.01","u",T0)
except BillingError as e: print("approval", e.code)
x=p("captured","1000.00"); process_refund_request(x,"500.00","u",T0); print("at threshold ok", x.refunded_amount)
# idempotency
audit.clear(); x=p()
process_refund_request(x,"10.00","u",T0,idempotency_key="k1")
process_refund_request(x,"10.00","u",T0,idempotency_key="k1")
print("idem", x.refunded_amount, len(audit.events("payment_refunded")))
EOF"}

